  1	import { updateSearch } from "../../shared/router/index.ts";
  2	import { SESSION_STATUSES, type SessionStatus } from "../../shared/api/types.ts";
  3	
  4	// Фильтры списка живут только в URL. Здесь знают имена `query` и `status`; остальные параметры
  5	// (в том числе `scenario`) остаются нетронутыми.
  6	
  7	export interface SessionFilters {
  8	  query: string;
  9	  /** Пустая строка = «все статусы». */
 10	  status: SessionStatus | "";
 11	}
 12	
 13	export interface FilterUpdate {
 14	  query?: string;
 15	  status?: SessionStatus | "";
 16	}
 17	
 18	function isStatus(value: string): value is SessionStatus {
 19	  return (SESSION_STATUSES as readonly string[]).includes(value);
 20	}
 21	
 22	/** Чтение из search: `query` после trim, невалидный `status` = «все» (на сервер не уходит). */
 23	export function readFilters(search: string): SessionFilters {
 24	  const params = new URLSearchParams(search);
 25	  const rawStatus = params.get("status") ?? "";
 26	  return {
 27	    query: (params.get("query") ?? "").trim(),
 28	    status: isStatus(rawStatus) ? rawStatus : "",
 29	  };
 30	}
 31	
 32	/** Новый search с обновлёнными `query`/`status`; пустое значение удаляет параметр. */
 33	export function writeFilters(search: string, update: FilterUpdate): string {
 34	  const updates: Record<string, string> = {};
 35	  if (update.query !== undefined) updates.query = update.query.trim();
 36	  if (update.status !== undefined) updates.status = update.status;
 37	  return updateSearch(search, updates);
 38	}
 39	
 40	/** Сброс удаляет только `query` и `status`. */
 41	export function clearFilters(search: string): string {
 42	  return updateSearch(search, { query: null, status: null });
 43	}
 44	
 45	export function hasActiveFilters(filters: SessionFilters): boolean {
 46	  return filters.query !== "" || filters.status !== "";
 47	}
 48	import { useCallback, useEffect, useState } from "react";
 49	import { getSessions } from "../../shared/api/client.ts";
 50	import type { ClientError } from "../../shared/api/errors.ts";
 51	import type { SessionsResponse } from "../../shared/api/types.ts";
 52	import type { SessionFilters } from "./filters.ts";
 53	
 54	export type SessionsStatus = "idle" | "loading" | "success" | "error";
 55	
 56	interface State {
 57	  status: SessionsStatus;
 58	  data: SessionsResponse | null;
 59	  error: ClientError | null;
 60	}
 61	
 62	interface Settled {
 63	  /** Ключ запроса, которому принадлежит результат. */
 64	  key: string;
 65	  data: SessionsResponse | null;
 66	  error: ClientError | null;
 67	}
 68	
 69	export interface UseSessionsResult extends State {
 70	  /** Идёт загрузка при уже имеющихся (прежних) данных: список приглушается. */
 71	  isRefreshing: boolean;
 72	  retry: () => void;
 73	}
 74	
 75	/**
 76	 * Список сессий по фильтрам. Запрос отменяется при смене фильтров и размонтировании, устаревшие
 77	 * ответы игнорируются. Прежние данные сохраняются на время `loading`. `reloadKey` — сигнал
 78	 * принудительного обновления (после создания сессии). Состояние `loading` выводится при рендере
 79	 * (ключ запроса не совпадает с ключом последнего результата), без setState в эффекте.
 80	 */
 81	export function useSessions(filters: SessionFilters, reloadKey = 0): UseSessionsResult {
 82	  const [settled, setSettled] = useState<Settled | null>(null);
 83	  const [attempt, setAttempt] = useState(0);
 84	  const { query, status } = filters;
 85	  const key = JSON.stringify([query, status, attempt, reloadKey]);
 86	
 87	  useEffect(() => {
 88	    const controller = new AbortController();
 89	    void getSessions({ query, status }, { signal: controller.signal }).then((result) => {
 90	      if (controller.signal.aborted) return;
 91	      if (result.ok) {
 92	        setSettled({ key, data: result.data, error: null });
 93	      } else if (!result.cancelled) {
 94	        setSettled({ key, data: null, error: result.error });
 95	      }
 96	    });
 97	    return () => controller.abort();
 98	  }, [key, query, status]);
 99	
100	  const retry = useCallback(() => setAttempt((n) => n + 1), []);
101	
102	  if (settled !== null && settled.key === key) {
103	    return {
104	      status: settled.error === null ? "success" : "error",
105	      data: settled.data,
106	      error: settled.error,
107	      isRefreshing: false,
108	      retry,
109	    };
110	  }
111	  const previous = settled?.data ?? null;
112	  return { status: "loading", data: previous, error: null, isRefreshing: previous !== null, retry };
113	}
114	import { useEffect, useRef, useState, type ChangeEvent } from "react";
115	import { SESSION_STATUSES, type SessionStatus } from "../../shared/api/types.ts";
116	import { navigate, readHistoryState, useLocation } from "../../shared/router/index.ts";
117	import { copy, STATUS_LABELS } from "./copy.ts";
118	import { clearFilters, hasActiveFilters, readFilters, writeFilters, type FilterUpdate } from "./filters.ts";
119	import { LiveStatus } from "./LiveStatus.tsx";
120	import { SessionRow } from "./SessionRow.tsx";
121	import { useSessions } from "./useSessions.ts";
122	
123	/** Пауза после последнего символа перед записью поиска в URL. */
124	export const SEARCH_DEBOUNCE_MS = 300;
125	
126	const SKELETON_ROWS = 5;
127	
128	interface SessionsPageProps {
129	  /** Открывает форму создания (состояние открытости живёт в app). */
130	  onCreateSession?: () => void;
131	  /** Сигнал принудительного перезапроса списка (после создания сессии). */
132	  reloadKey?: number;
133	}
134	
135	function isStatus(value: string): value is SessionStatus {
136	  return (SESSION_STATUSES as readonly string[]).includes(value);
137	}
138	
139	export function SessionsPage({ onCreateSession, reloadKey = 0 }: SessionsPageProps) {
140	  const { pathname, search } = useLocation();
141	  const filters = readFilters(search);
142	  const active = hasActiveFilters(filters);
143	  const { status, data, error, isRefreshing, retry } = useSessions(filters, reloadKey);
144	
145	  // Локальное transient-значение поля; в URL уходит с debounce. Внешнее изменение URL
146	  // (Назад, сброс) синхронизируется в поле во время рендера.
147	  const [text, setText] = useState(filters.query);
148	  const [seenQuery, setSeenQuery] = useState(filters.query);
