  7	export interface SessionFilters {
  8	  query: string;
  9	  /** Пустая строка = «все статусы». */
 10	  status: SessionStatus | "";
 11	}
 12	
 13	export interface FilterUpdate {
 14	  query?: string;
 15	  status?: SessionStatus | "";
 16	}
 17	
 18	function isStatus(value: string): value is SessionStatus {
 19	  return (SESSION_STATUSES as readonly string[]).includes(value);
 20	}
