 22	/** Чтение из search: `query` после trim, невалидный `status` = «все» (на сервер не уходит). */
 23	export function readFilters(search: string): SessionFilters {
 24	  const params = new URLSearchParams(search);
 25	  const rawStatus = params.get("status") ?? "";
 26	  return {
 27	    query: (params.get("query") ?? "").trim(),
 28	    status: isStatus(rawStatus) ? rawStatus : "",
 29	  };
 30	}
 31	
 32	/** Новый search с обновлёнными `query`/`status`; пустое значение удаляет параметр. */
 33	export function writeFilters(search: string, update: FilterUpdate): string {
 34	  const updates: Record<string, string> = {};
 35	  if (update.query !== undefined) updates.query = update.query.trim();
 36	  if (update.status !== undefined) updates.status = update.status;
 37	  return updateSearch(search, updates);
 38	}
