184	export type SessionDetailsStatus = "idle" | "loading" | "success" | "error" | "not-found";
185	
186	export interface UseSessionDetailsResult {
187	  status: SessionDetailsStatus;
188	  /** Только данные текущего `id`; при смене `id` прежние данные не показываются. */
189	  data: SessionDetails | null;
190	  error: ClientError | null;
191	  retry: () => void;
192	}
