201	/**
202	 * Детали сессии по `id`. Без `id` запрос не выполняется (`idle`). Запрос отменяется при смене `id`
203	 * и размонтировании. Состояние `loading` выводится при рендере (ключ не совпал с ключом результата).
204	 */
205	export function useSessionDetails(id: string | null): UseSessionDetailsResult {
206	  const [settled, setSettled] = useState<Settled | null>(null);
207	  const [attempt, setAttempt] = useState(0);
208	  const key = JSON.stringify([id, attempt]);
209	
210	  useEffect(() => {
211	    if (id === null) return;
212	    const controller = new AbortController();
213	    void getSessionDetails(id, { signal: controller.signal }).then((result) => {
214	      if (controller.signal.aborted) return;
215	      if (result.ok) {
216	        setSettled({ key, data: result.data, error: null });
217	      } else if (!result.cancelled) {
218	        setSettled({ key, data: null, error: result.error });
219	      }
220	    });
221	    return () => controller.abort();
222	  }, [id, key]);
223	
224	  const retry = useCallback(() => setAttempt((n) => n + 1), []);
225	
226	  if (id === null) return { status: "idle", data: null, error: null, retry };
227	  if (settled === null || settled.key !== key) {
228	    return { status: "loading", data: null, error: null, retry };
229	  }
230	  if (settled.error === null) {
231	    return { status: "success", data: settled.data, error: null, retry };
232	  }
233	  const notFound = isApiError(settled.error, "SESSION_NOT_FOUND");
234	  return { status: notFound ? "not-found" : "error", data: null, error: settled.error, retry };
235	}
