346	export function SessionDetailsDialog({ id }: SessionDetailsDialogProps) {
347	  const { search } = useLocation();
348	  const { status, data, retry } = useSessionDetails(id);
349	  const dialogRef = useRef<HTMLDialogElement>(null);
