351	  const closing = useRef(false);
352	
353	  // Синхронизация с URL: showModal при монтировании, close и возврат фокуса при размонтировании.
354	  useEffect(() => {
355	    const dialog = dialogRef.current;
356	    if (dialog === null) return;
357	    if (!dialog.open) dialog.showModal();
358	    headingRef.current?.focus({ preventScroll: true });
359	    return () => {
360	      if (dialog.open) dialog.close();
361	      restoreFocus(id);
