365	  // Если нажатая кнопка исчезла (Try again), фокус возвращается на h2 после окончания загрузки.
366	  useEffect(() => {
367	    if (status === "loading" || status === "idle") return;
368	    const active = document.activeElement;
369	    if (active === null || active === document.body || active === dialogRef.current) {
370	      headingRef.current?.focus({ preventScroll: true });
371	    }
372	  }, [status]);
373	
374	  function close(): void {
375	    if (closing.current) return;
376	    closing.current = true;
377	    if (cameFromList()) {
378	      goBack();
379	    } else {
380	      navigate(`/sessions${search}`, { replace: true });
381	    }
382	  }
