399	      className="dialog"
400	      aria-labelledby="details-title"
401	      onCancel={handleCancel}
402	      onClick={handleBackdropClick}
403	    >
404	      <div className="dialog-frame">
405	        <header className="dialog-header">
406	          <div className="dialog-header-main">
407	            <span className="details-label">{copy.details.label}</span>
408	            <h2 id="details-title" ref={headingRef} tabIndex={-1}>
