440	              <p className="muted">{copy.details.errorBody}</p>
441	              <button type="button" className="button button-primary" onClick={retry}>
442	                {copy.tryAgain}
443	              </button>
444	            </div>
445	          ) : null}
446	
447	          {isNotFound ? (
