 20	export type FieldName = keyof FormValues;
 21	
 22	/** Ключ ошибки: поля формы плюс `startsAt` (ошибка пары Date/Start time). */
 23	export type ErrorKey = FieldName | "startsAt";
 24	export type FormErrors = Partial<Record<ErrorKey, string>>;
 25	
 26	/** Порядок ошибок = порядок полей в DOM (для фокуса на первое невалидное). */
 27	export const ERROR_ORDER: readonly ErrorKey[] = [
 28	  "title",
 29	  "type",
 30	  "date",
 31	  "time",
 32	  "startsAt",
 33	  "duration",
 34	  "capacity",
 35	  "coachId",
 36	  "locationName",
 37	  "locationAddress",
 38	  "visibility",
 39	  "description",
 40	  "trainerNotes",
 41	];
