 43	export const INITIAL_VALUES: FormValues = {
 44	  title: "",
 45	  type: "training",
 46	  date: "",
 47	  time: "",
 48	  duration: "",
 49	  capacity: "",
 50	  coachId: "",
 51	  locationName: "",
 52	  locationAddress: "",
 53	  visibility: "public",
 54	  description: "",
 55	  trainerNotes: "",
 56	};
