 58	export function isDirty(values: FormValues): boolean {
 59	  return (Object.keys(INITIAL_VALUES) as FieldName[]).some((key) => values[key] !== INITIAL_VALUES[key]);
 60	}
 61	
 62	/** Ключ серверного `fieldErrors`, который снимается при редактировании поля. */
 63	export const FIELD_SERVER_KEY: Record<FieldName, string> = {
 64	  title: "title",
 65	  type: "type",
 66	  date: "startsAt",
 67	  time: "startsAt",
 68	  duration: "durationMinutes",
 69	  capacity: "capacity",
 70	  coachId: "coachId",
 71	  locationName: "locationName",
 72	  locationAddress: "locationAddress",
 73	  visibility: "visibility",
 74	  description: "description",
 75	  trainerNotes: "trainerNotes",
 76	};
 77	
 78	const SERVER_KEY_TO_ERROR: Record<string, ErrorKey> = {
 79	  title: "title",
 80	  type: "type",
 81	  startsAt: "startsAt",
 82	  durationMinutes: "duration",
 83	  capacity: "capacity",
 84	  coachId: "coachId",
 85	  locationName: "locationName",
 86	  locationAddress: "locationAddress",
 87	  visibility: "visibility",
 88	  description: "description",
 89	  trainerNotes: "trainerNotes",
 90	};
 91	
 92	export interface SplitServerErrors {
 93	  /** Ошибки, у которых есть поле. */
 94	  fields: FormErrors;
 95	  /** Тексты ключей без поля: уходят в блок формы (D-7). */
 96	  unmatched: string[];
 97	}
 98	
 99	export function splitServerErrors(fieldErrors: Record<string, string>): SplitServerErrors {
100	  const fields: FormErrors = {};
101	  const unmatched: string[] = [];
102	  for (const [key, message] of Object.entries(fieldErrors)) {
103	    const target = Object.hasOwn(SERVER_KEY_TO_ERROR, key) ? SERVER_KEY_TO_ERROR[key] : undefined;
104	    if (target === undefined) unmatched.push(message);
105	    else fields[target] = message;
106	  }
107	  return { fields, unmatched };
108	}
