110	/** Запрос API из уже проверенных значений; `null`, если дата и время не собираются в `startsAt`. */
111	export function toRequest(values: FormValues): CreateSessionRequest | null {
112	  const start = localToIsoUtc(values.date, values.time);
113	  if (!start.ok) return null;
114	  const description = values.description.trim();
115	  const trainerNotes = values.trainerNotes.trim();
116	  const request: CreateSessionRequest = {
117	    title: values.title.trim(),
118	    type: values.type,
119	    startsAt: start.iso,
120	    durationMinutes: Number(values.duration.trim()),
121	    coachId: values.coachId,
122	    locationName: values.locationName.trim(),
123	    locationAddress: values.locationAddress.trim(),
124	    capacity: Number(values.capacity.trim()),
125	    visibility: values.visibility,
126	  };
127	  if (description !== "") request.description = description;
128	  if (trainerNotes !== "") request.trainerNotes = trainerNotes;
129	  return request;
130	}
131	import { isFuture, localToIsoUtc } from "../../shared/lib/datetime.ts";
132	import type { FormErrors, FormValues } from "./form-values.ts";
133	import { copy } from "./copy.ts";
134	
135	export interface ValidationContext {
136	  /** Текущий момент, мс. */
137	  now: number;
138	  /** id тренеров из последнего успешного `GET /api/coaches`; пусто = выбрать нельзя. */
139	  coachIds: readonly string[];
140	}
141	
142	export const LIMITS = {
143	  title: { min: 3, max: 80 },
144	  duration: { min: 30, max: 240 },
145	  capacity: { min: 1, max: 100 },
146	  locationName: { min: 2, max: 80 },
147	  locationAddress: { min: 3, max: 120 },
148	  trainerNotes: { max: 500 },
149	  /** UI-допущение A-13, не AC. */
150	  description: { max: 1000 },
151	} as const;
152	
153	function outside(value: string, min: number, max: number): boolean {
154	  const length = value.trim().length;
155	  return length < min || length > max;
156	}
157	
158	function notWholeNumberIn(raw: string, min: number, max: number): boolean {
159	  const text = raw.trim();
160	  if (!/^\d+$/.test(text)) return true;
161	  const n = Number(text);
162	  return n < min || n > max;
163	}
164	
165	/** Чистая проверка по AC-3.1–3.8 на trim-значениях. Ошибки у поля или у пары `startsAt`. */
166	export function validate(values: FormValues, context: ValidationContext): FormErrors {
167	  const errors: FormErrors = {};
168	  const { title, duration, capacity, locationName, locationAddress, trainerNotes, description } = LIMITS;
169	
170	  if (outside(values.title, title.min, title.max)) errors.title = copy.errors.title;
171	
172	  const date = values.date.trim();
173	  const time = values.time.trim();
174	  if (date === "") errors.date = copy.errors.date;
175	  if (time === "") errors.time = copy.errors.time;
176	  if (date !== "" && time !== "") {
177	    const start = localToIsoUtc(date, time);
178	    if (!start.ok) errors.startsAt = copy.errors.nonexistentDateTime;
179	    else if (!isFuture(start.iso, context.now)) errors.startsAt = copy.errors.pastDateTime;
180	  }
181	
182	  if (notWholeNumberIn(values.duration, duration.min, duration.max)) errors.duration = copy.errors.duration;
183	  if (notWholeNumberIn(values.capacity, capacity.min, capacity.max)) errors.capacity = copy.errors.capacity;
184	  if (values.coachId === "" || !context.coachIds.includes(values.coachId)) {
185	    errors.coachId = copy.errors.coach;
186	  }
187	  if (outside(values.locationName, locationName.min, locationName.max)) {
188	    errors.locationName = copy.errors.locationName;
189	  }
190	  if (outside(values.locationAddress, locationAddress.min, locationAddress.max)) {
191	    errors.locationAddress = copy.errors.locationAddress;
