300	  const [attempt, setAttempt] = useState(0);
301	
302	  useEffect(() => {
303	    const controller = new AbortController();
304	    void getCoaches({ signal: controller.signal }).then((result) => {
305	      if (controller.signal.aborted) return;
306	      if (result.ok) {
307	        setSettled({ key: attempt, coaches: result.data.data, error: null });
308	      } else if (!result.cancelled) {
309	        setSettled({ key: attempt, coaches: NONE, error: result.error });
310	      }
311	    });
312	    return () => controller.abort();
313	  }, [attempt]);
314	
315	  const retry = useCallback(() => setAttempt((n) => n + 1), []);
316	
317	  if (settled === null || settled.key !== attempt) {
318	    return { status: "loading", coaches: NONE, error: null, retry };
319	  }
320	  return {
321	    status: settled.error === null ? "success" : "error",
322	    coaches: settled.coaches,
323	    error: settled.error,
324	    retry,
325	  };
326	}
