346	export interface UseCreateSessionResult {
347	  status: CreateStatus;
348	  session: SessionDetails | null;
349	  error: ClientError | null;
350	  /** Серверные `fieldErrors` по ключам контракта. */
351	  fieldErrors: Record<string, string>;
352	  submit: (request: CreateSessionRequest) => Promise<SubmitOutcome>;
353	  /** Снимает серверную ошибку поля при его редактировании. */
354	  clearFieldError: (serverKey: string) => void;
355	  reset: () => void;
356	}
