360	/**
361	 * Отправка формы. Guard (api-integration, раздел 9): `createSession` не вызывается, пока список
362	 * тренеров не загружен успешно или `coachId` не входит в него. Флаг pending (ref, срабатывает
363	 * синхронно) блокирует повторный вызов; POST не отменяется.
364	 */
365	export function useCreateSession(guard: CoachesGuard): UseCreateSessionResult {
366	  const [status, setStatus] = useState<CreateStatus>("idle");
367	  const [session, setSession] = useState<SessionDetails | null>(null);
368	  const [error, setError] = useState<ClientError | null>(null);
369	  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>(NO_ERRORS);
370	  const pending = useRef(false);
371	  const { status: coachesStatus, coaches } = guard;
372	
373	  const submit = useCallback(
374	    async (request: CreateSessionRequest): Promise<SubmitOutcome> => {
375	      if (pending.current) return { kind: "ignored" };
376	      if (coachesStatus !== "success" || !coaches.some((coach) => coach.id === request.coachId)) {
377	        return { kind: "blocked" };
378	      }
379	      pending.current = true;
380	      setStatus("pending");
381	      setError(null);
382	      setFieldErrors(NO_ERRORS);
383	      const result = await createSession(request);
384	      pending.current = false;
385	      if (result.ok) {
386	        setSession(result.data);
387	        setStatus("success");
388	        return { kind: "success", session: result.data };
389	      }
390	      if (result.cancelled) {
391	        setStatus("idle");
392	        return { kind: "ignored" };
393	      }
394	      setError(result.error);
395	      setFieldErrors(result.error.kind === "api" ? (result.error.fieldErrors ?? NO_ERRORS) : NO_ERRORS);
396	      setStatus("error");
397	      return { kind: "error", error: result.error };
398	    },
399	    [coachesStatus, coaches],
400	  );
401	
402	  const clearFieldError = useCallback((serverKey: string) => {
403	    setFieldErrors((current) => {
404	      if (!Object.hasOwn(current, serverKey)) return current;
405	      const { [serverKey]: _removed, ...rest } = current;
406	      return rest;
407	    });
408	  }, []);
409	
410	  const reset = useCallback(() => {
411	    if (pending.current) return;
412	    setStatus("idle");
413	    setSession(null);
414	    setError(null);
415	    setFieldErrors(NO_ERRORS);
416	  }, []);
417	
418	  return { status, session, error, fieldErrors, submit, clearFieldError, reset };
419	}
