292	const NONE: readonly CoachSummary[] = [];
293	
294	/**
295	 * Тренеры для формы: запрос при монтировании (форма открыта), без автоповтора. `retry` отменяет
296	 * незавершённый запрос и стартует новый. Статус `loading` выводится при рендере.
297	 */
298	export function useCoaches(): UseCoachesResult {
299	  const [settled, setSettled] = useState<Settled | null>(null);
300	  const [attempt, setAttempt] = useState(0);
301	
302	  useEffect(() => {
303	    const controller = new AbortController();
304	    void getCoaches({ signal: controller.signal }).then((result) => {
305	      if (controller.signal.aborted) return;
306	      if (result.ok) {
307	        setSettled({ key: attempt, coaches: result.data.data, error: null });
308	      } else if (!result.cancelled) {
309	        setSettled({ key: attempt, coaches: NONE, error: result.error });
310	      }
311	    });
312	    return () => controller.abort();
313	  }, [attempt]);
314	
315	  const retry = useCallback(() => setAttempt((n) => n + 1), []);
316	
317	  if (settled === null || settled.key !== attempt) {
318	    return { status: "loading", coaches: NONE, error: null, retry };
319	  }
320	  return {
321	    status: settled.error === null ? "success" : "error",
322	    coaches: settled.coaches,
323	    error: settled.error,
324	    retry,
325	  };
326	}
327	import { useCallback, useRef, useState } from "react";
328	import { createSession } from "../../shared/api/client.ts";
329	import type { ClientError } from "../../shared/api/errors.ts";
330	import type { CoachSummary, CreateSessionRequest, SessionDetails } from "../../shared/api/types.ts";
331	import type { CoachesStatus } from "./useCoaches.ts";
332	
333	export type CreateStatus = "idle" | "pending" | "success" | "error";
334	
335	export type SubmitOutcome =
336	  | { kind: "ignored" }
337	  | { kind: "blocked" }
338	  | { kind: "success"; session: SessionDetails }
339	  | { kind: "error"; error: ClientError };
340	
341	export interface CoachesGuard {
342	  status: CoachesStatus;
343	  coaches: readonly CoachSummary[];
344	}
345	
346	export interface UseCreateSessionResult {
347	  status: CreateStatus;
348	  session: SessionDetails | null;
349	  error: ClientError | null;
350	  /** Серверные `fieldErrors` по ключам контракта. */
351	  fieldErrors: Record<string, string>;
352	  submit: (request: CreateSessionRequest) => Promise<SubmitOutcome>;
353	  /** Снимает серверную ошибку поля при его редактировании. */
354	  clearFieldError: (serverKey: string) => void;
355	  reset: () => void;
356	}
357	
358	const NO_ERRORS: Record<string, string> = {};
359	
360	/**
361	 * Отправка формы. Guard (api-integration, раздел 9): `createSession` не вызывается, пока список
362	 * тренеров не загружен успешно или `coachId` не входит в него. Флаг pending (ref, срабатывает
363	 * синхронно) блокирует повторный вызов; POST не отменяется.
364	 */
365	export function useCreateSession(guard: CoachesGuard): UseCreateSessionResult {
366	  const [status, setStatus] = useState<CreateStatus>("idle");
367	  const [session, setSession] = useState<SessionDetails | null>(null);
368	  const [error, setError] = useState<ClientError | null>(null);
369	  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>(NO_ERRORS);
370	  const pending = useRef(false);
371	  const { status: coachesStatus, coaches } = guard;
372	
373	  const submit = useCallback(
374	    async (request: CreateSessionRequest): Promise<SubmitOutcome> => {
375	      if (pending.current) return { kind: "ignored" };
376	      if (coachesStatus !== "success" || !coaches.some((coach) => coach.id === request.coachId)) {
377	        return { kind: "blocked" };
378	      }
379	      pending.current = true;
380	      setStatus("pending");
381	      setError(null);
382	      setFieldErrors(NO_ERRORS);
383	      const result = await createSession(request);
384	      pending.current = false;
385	      if (result.ok) {
386	        setSession(result.data);
387	        setStatus("success");
388	        return { kind: "success", session: result.data };
389	      }
390	      if (result.cancelled) {
391	        setStatus("idle");
392	        return { kind: "ignored" };
393	      }
394	      setError(result.error);
395	      setFieldErrors(result.error.kind === "api" ? (result.error.fieldErrors ?? NO_ERRORS) : NO_ERRORS);
396	      setStatus("error");
397	      return { kind: "error", error: result.error };
398	    },
399	    [coachesStatus, coaches],
400	  );
401	
402	  const clearFieldError = useCallback((serverKey: string) => {
403	    setFieldErrors((current) => {
404	      if (!Object.hasOwn(current, serverKey)) return current;
405	      const { [serverKey]: _removed, ...rest } = current;
406	      return rest;
407	    });
408	  }, []);
409	
410	  const reset = useCallback(() => {
411	    if (pending.current) return;
412	    setStatus("idle");
413	    setSession(null);
414	    setError(null);
415	    setFieldErrors(NO_ERRORS);
416	  }, []);
417	
418	  return { status, session, error, fieldErrors, submit, clearFieldError, reset };
419	}
420	import { useRef, useState, type Ref } from "react";
421	import type { SessionDetails } from "../../shared/api/types.ts";
422	import { formatSummaryDateTime } from "../../shared/lib/datetime.ts";
423	import { copy } from "./copy.ts";
424	
425	interface SuccessScreenProps {
426	  session: SessionDetails;
427	  filtersActive: boolean;
428	  headingRef: Ref<HTMLHeadingElement>;
429	  onOpenSession: () => void;
430	  onCreateAnother: () => void;
431	  onClearFilters: () => void;
432	  onClose: () => void;
433	}
434	
435	/** Экран успеха внутри диалога (ui-design 7): заголовок и сводка в polite-статусе. */
436	export function SuccessScreen({
437	  session,
438	  filtersActive,
439	  headingRef,
440	  onOpenSession,
441	  onCreateAnother,
442	  onClearFilters,
443	  onClose,
444	}: SuccessScreenProps) {
445	  const [cleared, setCleared] = useState(false);
446	  const openRef = useRef<HTMLButtonElement>(null);
447	
448	  function handleClearFilters(): void {
449	    // Фокус переносится до того, как кнопка исчезнет.
450	    openRef.current?.focus();
451	    setCleared(true);
452	    onClearFilters();
453	  }
454	
455	  return (
456	    <>
457	      <div className="dialog-body">
458	        <div role="status" className="success-status">
459	          <h2 id="create-title" ref={headingRef} tabIndex={-1}>
460	            {copy.success.title}
461	          </h2>
462	          <p>{copy.success.summary(session.title, formatSummaryDateTime(session.startsAt))}</p>
463	          {cleared ? <p>{copy.success.filtersCleared}</p> : null}
464	        </div>
465	        {filtersActive && !cleared ? (
466	          <div className="success-filters">
467	            <p className="muted">{copy.success.filtersActive}</p>
468	            <button type="button" className="button button-secondary" onClick={handleClearFilters}>
469	              {copy.success.clearFilters}
470	            </button>
471	          </div>
472	        ) : null}
473	      </div>
474	      <footer className="dialog-footer form-footer">
475	        <button type="button" className="button button-secondary" onClick={onClose}>
476	          {copy.success.close}
477	        </button>
478	        <button type="button" className="button button-secondary" onClick={onCreateAnother}>
479	          {copy.success.another}
480	        </button>
481	        <button ref={openRef} type="button" className="button button-primary" onClick={onOpenSession}>
482	          {copy.success.open}
483	        </button>
484	      </footer>
485	    </>
486	  );
487	}

