31	
32	export interface CreateSessionDialogProps {
33	  /** Активны ли фильтры списка (подсказка и «Clear filters» на экране успеха). */
34	  filtersActive: boolean;
35	  /** Закрытие диалога; `refetch` — исход POST был неизвестен (сеть, malformed), список нужно перезапросить. */
36	  onClose: (result: { refetch: boolean }) => void;
37	  /** Сессия создана (201): владелец списка перезапрашивает его. */
38	  onCreated: () => void;
39	  onOpenSession: (id: string) => void;
40	  onClearFilters: () => void;
41	}
42	
43	const FIELD_IDS: Record<ErrorKey, string> = {
44	  title: "cs-title",
45	  type: "cs-type",
46	  date: "cs-date",
47	  time: "cs-time",
48	  startsAt: "cs-date",
49	  duration: "cs-duration",
50	  capacity: "cs-capacity",
51	  coachId: "cs-coach",
52	  locationName: "cs-location-name",
53	  locationAddress: "cs-location-address",
54	  visibility: "cs-visibility-public",
55	  description: "cs-description",
56	  trainerNotes: "cs-notes",
57	};
58	
59	const COACH_RETRY_ID = "cs-coaches-retry";
60	const DESCRIPTION_COUNTER_FROM = 800;
61	const NOTES_COUNTER_FROM = 400;
62	
63	/** Фокус при открытии: Title на десктопе, заголовок при coarse-указателе (клавиатура не поднимается). */
64	function focusInitial(dialog: HTMLElement): void {
65	  const coarse = typeof window.matchMedia === "function" && window.matchMedia("(pointer: coarse)").matches;
66	  const target = coarse ? dialog.querySelector<HTMLElement>("h2") : document.getElementById(FIELD_IDS.title);
67	  target?.focus({ preventScroll: true });
68	}
69	
70	function restoreFocus(opener: HTMLElement | null): void {
71	  // Открыватель мог исчезнуть (кнопка пустого состояния): запасной вариант — кнопка в шапке.
72	  const target = opener?.isConnected ? opener : document.querySelector<HTMLElement>("[data-create-trigger]");
73	  target?.focus();
74	}
75	
76	function isSessionType(value: string): value is SessionType {
77	  return (SESSION_TYPES as readonly string[]).includes(value);
78	}
79	
80	function isVisibility(value: string): value is Visibility {
81	  return (VISIBILITIES as readonly string[]).includes(value);
82	}
83	
84	/**
85	 * Форма создания во втором нативном `<dialog>` без URL. Монтируется только пока форма открыта
86	 * (состояние открытости в `app`); при размонтировании закрывает диалог и возвращает фокус.
87	 */
88	export function CreateSessionDialog({
89	  filtersActive,
90	  onClose,
91	  onCreated,
92	  onOpenSession,
93	  onClearFilters,
94	}: CreateSessionDialogProps) {
95	  const coaches = useCoaches();
96	  const create = useCreateSession(coaches);
97	  const [values, setValues] = useState<FormValues>(INITIAL_VALUES);
98	  const [touched, setTouched] = useState<Partial<Record<FieldName, true>>>({});
99	  const [submitted, setSubmitted] = useState(false);
100	  const [attention, setAttention] = useState(0);
101	  const [confirming, setConfirming] = useState(false);
102	  const [seenCoaches, setSeenCoaches] = useState(coaches.coaches);
103	
104	  const dialogRef = useRef<HTMLDialogElement>(null);
105	  const headingRef = useRef<HTMLHeadingElement>(null);
106	  const submitRef = useRef<HTMLButtonElement>(null);
107	  const keepRef = useRef<HTMLButtonElement>(null);
108	  const cancelRef = useRef<HTMLButtonElement>(null);
109	  const blockRef = useRef<HTMLDivElement>(null);
110	  const selectRef = useRef<HTMLSelectElement>(null);
111	  const closing = useRef(false);
112	  const skipRestore = useRef(false);
113	  const outcomeUnknown = useRef(false);
114	  const coachRetrying = useRef(false);
115	  const restoreAfterConfirm = useRef<HTMLElement | null>(null);
116	  const beforeConfirm = useRef<HTMLElement | null>(null);
117	
118	  const pending = create.status === "pending";
119	  const createdSession = create.status === "success" ? create.session : null;
120	  const succeeded = createdSession !== null;
121	  const coachIds = coaches.status === "success" ? coaches.coaches.map((coach) => coach.id) : [];
122	
123	  // Выбранный тренер исчез из обновлённого списка: выбор сбрасывается с ошибкой (ui-design 6.4).
124	  if (coaches.status === "success" && seenCoaches !== coaches.coaches) {
125	    setSeenCoaches(coaches.coaches);
126	    if (values.coachId !== "" && !coachIds.includes(values.coachId)) {
127	      setValues({ ...values, coachId: "" });
128	      setTouched({ ...touched, coachId: true });
129	    }
130	  }
131	
132	  const clientErrors = validate(values, { now: currentTime(), coachIds });
133	  const server = splitServerErrors(create.fieldErrors);
134	  const unmatchedErrors = server.unmatched;
135	
136	  function shown(key: ErrorKey): string | undefined {
137	    const serverMessage = server.fields[key];
138	    if (serverMessage !== undefined) return serverMessage;
139	    const clientMessage = clientErrors[key];
140	    if (clientMessage === undefined) return undefined;
141	    if (submitted) return clientMessage;
142	    if (key === "startsAt") return touched.date && touched.time ? clientMessage : undefined;
143	    return touched[key] ? clientMessage : undefined;
144	  }
145	
146	  const errors: Partial<Record<ErrorKey, string>> = {};
147	  for (const key of ERROR_ORDER) errors[key] = shown(key);
148	
149	  // Открытие: showModal, фокус; закрытие при размонтировании и возврат фокуса на открыватель.
150	  useEffect(() => {
151	    const dialog = dialogRef.current;
152	    if (dialog === null) return;
153	    closing.current = false;
154	    const active = document.activeElement;
155	    const opener = active instanceof HTMLElement ? active : null;
156	    if (!dialog.open) dialog.showModal();
157	    return () => {
158	      closing.current = true;
159	      if (dialog.open) dialog.close();
160	      if (!skipRestore.current) restoreFocus(opener);
161	    };
162	  }, []);
163	
164	  // Фокус по виду: форма (в том числе «Create another») или экран успеха.
165	  useEffect(() => {
166	    const dialog = dialogRef.current;
167	    if (dialog === null) return;
168	    if (succeeded) headingRef.current?.focus({ preventScroll: true });
169	    else focusInitial(dialog);
170	  }, [succeeded]);
171	
172	  // Подтверждение закрытия: фокус на «Keep editing»; при отказе возврат туда, где был фокус.
173	  useEffect(() => {
174	    if (confirming) {
175	      keepRef.current?.focus();
176	      return;
177	    }
178	    const previous = restoreAfterConfirm.current;
179	    if (previous === null) return;
180	    restoreAfterConfirm.current = null;
181	    (previous.isConnected ? previous : cancelRef.current)?.focus();
182	  }, [confirming]);
183	
184	  // Повтор загрузки тренеров: фокус на select после успеха, на кнопку повтора после новой ошибки.
185	  useEffect(() => {
186	    if (!coachRetrying.current || coaches.status === "loading") return;
187	    coachRetrying.current = false;
188	    if (coaches.status === "success" && coaches.coaches.length > 0) selectRef.current?.focus();
189	    else document.getElementById(COACH_RETRY_ID)?.focus();
190	  }, [coaches.status, coaches.coaches]);
191	
192	  function focusField(key: ErrorKey): void {
193	    const coachProblem = key === "coachId" && !(coaches.status === "success" && coaches.coaches.length > 0);
194	    const id = coachProblem ? COACH_RETRY_ID : FIELD_IDS[key];
195	    document.getElementById(id)?.focus();
196	  }
197	
198	  const reportCreateError = useEffectEvent(() => {
199	    const first = ERROR_ORDER.find((key) => server.fields[key] !== undefined);
200	    if (first === undefined) blockRef.current?.focus();
201	    else focusField(first);
202	  });
203	  useEffect(() => {
204	    if (create.error !== null) reportCreateError();
205	  }, [create.error]);
206	
207	  function doClose(): void {
208	    onClose({ refetch: outcomeUnknown.current });
209	  }
210	
211	  function requestClose(): void {
212	    if (pending) return;
213	    if (succeeded || !isDirty(values)) {
214	      doClose();
215	      return;
216	    }
217	    const active = document.activeElement;
218	    beforeConfirm.current = active instanceof HTMLElement ? active : null;
219	    setConfirming(true);
220	  }
221	
222	  function keepEditing(): void {
223	    restoreAfterConfirm.current = beforeConfirm.current ?? cancelRef.current;
224	    setConfirming(false);
225	  }
226	
227	  function handleCancelEvent(event: SyntheticEvent<HTMLDialogElement>): void {
228	    // Esc: нативное закрытие отменяется, решает процедура закрытия.
229	    event.preventDefault();
230	    if (confirming) return;
231	    requestClose();
232	  }
233	
234	  function handleNativeClose(): void {
235	    // Браузер мог закрыть диалог повторным Esc несмотря на отменённый `cancel`: возвращаем модальность.
236	    const dialog = dialogRef.current;
237	    // Закрытие нами (cleanup) и StrictMode-перемонтирование (диалог уже снова открыт) не обрабатываются.
238	    if (closing.current || dialog === null || dialog.open) return;
239	    dialog.showModal();
240	    if (!confirming) requestClose();
241	  }
242	
243	  function change(name: FieldName, value: string): void {
244	    setValues((current) => ({ ...current, [name]: value }));
245	    create.clearFieldError(FIELD_SERVER_KEY[name]);
246	  }
247	
248	  function inputProps(name: FieldName) {
249	    return {
250	      name,
251	      value: values[name],
252	      readOnly: pending,
253	      onChange: (event: ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => change(name, event.target.value),
254	      onBlur: () => setTouched((current) => ({ ...current, [name]: true })),
255	    };
256	  }
257	
258	  async function handleSubmit(event: FormEvent<HTMLFormElement>): Promise<void> {
259	    event.preventDefault();
260	    if (pending || confirming) return;
261	    setSubmitted(true);
262	    const invalid = ERROR_ORDER.filter((key) => clientErrors[key] !== undefined);
263	    if (invalid.length > 0) {
264	      setAttention(invalid.length);
265	      focusField(invalid[0]);
266	      return;
267	    }
268	    setAttention(0);
269	    const request = toRequest(values);
270	    if (request === null) return;
271	    // Фокус остаётся на кнопке отправки: поля блокируются, фокус не теряется.
272	    submitRef.current?.focus();
273	    const outcome = await create.submit(request);
274	    if (outcome.kind === "success") onCreated();
275	    else if (outcome.kind === "error" && outcome.error.kind !== "api") outcomeUnknown.current = true;
276	    else if (outcome.kind === "blocked") focusField("coachId");
277	  }
278	
279	  function createAnother(): void {
280	    setValues(INITIAL_VALUES);
281	    setTouched({});
282	    setSubmitted(false);
283	    setAttention(0);
284	    create.reset();
285	  }
286	
287	  function openSession(): void {
288	    if (create.session === null) return;
289	    skipRestore.current = true;
290	    onOpenSession(create.session.id);
291	  }
292	
293	  const startsAtShown = errors.startsAt !== undefined;
294	  const timeZone = formatTimeZoneName(currentTime());
295	  const descriptionLength = values.description.length;
296	  const notesLength = values.trainerNotes.length;
297	  const coachFieldError = errors.coachId;
298	  const coachListUsable = coaches.status === "success" && coaches.coaches.length > 0;
299	
300	  return (
301	    <dialog
302	      ref={dialogRef}
303	      className="dialog form-dialog"
304	      aria-labelledby="create-title"
305	      onCancel={handleCancelEvent}
306	      onClose={handleNativeClose}
307	    >
308	      <div className="dialog-frame">
309	        <header className="dialog-header">
310	          <div className="dialog-header-main">
311	            {succeeded ? null : (
312	              <h2 id="create-title" ref={headingRef} tabIndex={-1}>
313	                {copy.dialogTitle}
314	              </h2>
315	            )}
316	          </div>
317	          <button
318	            type="button"
319	            className="dialog-close"
320	            aria-label={copy.closeAria}
321	            disabled={pending}
322	            onClick={requestClose}
323	          >
324	            <span aria-hidden="true">×</span>
325	          </button>
326	        </header>
327	
328	        {createdSession !== null ? (
329	          <SuccessScreen
330	            session={createdSession}
331	            filtersActive={filtersActive}
332	            headingRef={headingRef}
333	            onOpenSession={openSession}
334	            onCreateAnother={createAnother}
335	            onClearFilters={onClearFilters}
336	            onClose={doClose}
337	          />
338	        ) : (
339	          <form className="create-form" noValidate aria-busy={pending} onSubmit={handleSubmit}>
