.session-row + .session-row {
  border-top: 1px solid var(--border);
}

.session-row:hover {
  background: var(--surface-muted);
}

.cell {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  overflow-wrap: anywhere;
  font-variant-numeric: tabular-nums;
}

.cell-capacity {
  font-variant-numeric: tabular-nums;
}

.start-wide {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.start-narrow {
  display: none;
}

.session-link {
  font-weight: 700;
  color: var(--text);
  text-decoration: none;
}

.session-link:hover,
.session-link:focus-visible {
  text-decoration: underline;
}

/* Фокус рисуется на всей строке (ссылка растянута на неё), а не на тексте названия. */
.session-link:focus-visible {
  outline: none;
}

.session-row:has(.session-link:focus-visible) {
  outline: 2px solid var(--focus);
  outline-offset: -2px;
}

/* Растянутая область клика на всю строку */
.session-link::after {
  content: "";
  position: absolute;
  inset: 0;
}

/* Бейдж статуса: иконка и текст */
.status-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 28px;

.skeleton-line {
  display: block;
  height: 16px;
  width: 60%;
  background: var(--surface-muted);
  border-radius: var(--radius);
  animation: skeleton-pulse 1.2s ease-in-out infinite;
}

@keyframes skeleton-pulse {
  50% {
    opacity: 0.5;
  }
}

@media (prefers-reduced-motion: reduce) {
  .skeleton-line {
    animation: none;
  }
}

/* Общий каркас диалога (детали и форма создания): <dialog> > .dialog-frame > header, body, footer. */
body:has(dialog[open]) {
  overflow: hidden;
}

.dialog {
  width: min(560px, calc(100vw - 32px));
  max-height: calc(100dvh - 64px);
  padding: 0;
  color: var(--text);
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
}

.dialog[open] {
  display: block;
}

.dialog::backdrop {
  background: rgb(23 33 36 / 0.45);
}

/* Короткое появление: только opacity и transform; при reduce отключено (см. media ниже и index.css). */
.dialog[open] {
  animation: dialog-in 150ms ease-out;
}

@keyframes dialog-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .dialog[open] {
    animation: none;
  }
}

.dialog-frame {
  display: flex;
  flex-direction: column;
  max-height: calc(100dvh - 64px);
}

.dialog-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 16px 12px;
  border-bottom: 1px solid var(--border);
}

.dialog-header-main {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  min-width: 0;
}
  font-weight: 700;
  margin-bottom: 8px;
}

.success-filters {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  margin-top: 16px;
}

/* Мобильный (ui-design 4.3, 5.1, 11): строки стеком, цели касания 44px, поля 16px. */
@media (max-width: 720px) {
  .session-list-head {
    display: none;
  }

  .session-row {
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas:
      "status capacity"
      "session session"
      "start start"
      "coach coach";
    row-gap: 4px;
    min-height: 64px;
  }

  .cell-status {
    grid-area: status;
  }

  .cell-capacity {
    grid-area: capacity;
    text-align: right;
  }

  .cell-session {
    grid-area: session;
  }

  .cell-start {
    grid-area: start;
  }

  .start-wide {
    display: none;
  }

  .start-narrow {
    display: inline;
  }

  .cell-coach {
    grid-area: coach;
    color: var(--text-muted);
  }

  /* Поиск на всю ширину; ниже в одной строке статус и «Clear filters». */
  .toolbar-search {
    flex: 1 0 100%;
  }

  .toolbar-status {
    flex: 1 1 0;
  }

  .button,
  .toolbar input[type="search"],
  .toolbar select,
  .create-form input[type="text"],
  .create-form input[type="date"],
  .create-form input[type="time"],
  .create-form input[type="number"],
  .create-form select,
  .create-form textarea {
    min-height: 44px;
  }

  /* 16px: iOS не приближает экран при фокусе поля. */
  .toolbar input[type="search"],
  .toolbar select,
  .create-form input[type="text"],
  .create-form input[type="date"],
  .create-form input[type="time"],
  .create-form input[type="number"],
  .create-form select,
  .create-form textarea {
    font-size: 16px;
    line-height: 24px;
  }

  .radio-option {
    min-height: 44px;
  }

  .dialog-close {
    width: 44px;
    height: 44px;
  }
}

@media (max-width: 420px) {
  .page-header {
    flex-direction: column;
    align-items: stretch;
  }
}

/* Диалоги на весь экран (ui-design 5.1, 6.1). */
